"""Version 75 : transitions douces entre les pages, partagées par le site, l'appli et l'Académie."""
CSS = '\n/* version 75 : changements de page en fondu, sans à-coup (navigateurs récents), sinon simple apparition douce */\n@view-transition{navigation:auto}\n::view-transition-old(root){animation:vt-sort .22s ease both}::view-transition-new(root){animation:vt-entre .32s cubic-bezier(.2,.8,.2,1) both}\n@keyframes vt-sort{to{opacity:0}}@keyframes vt-entre{from{opacity:0;transform:translateY(6px)}}\n@supports not (view-transition-name:none){@media (prefers-reduced-motion:no-preference){body{animation:vt-entre .3s ease-out both}}}\n@media (prefers-reduced-motion:reduce){@view-transition{navigation:none}}\n'
